import click


def _get_completions(cli, args, incomplete):
    from click.shell_completion import ShellComplete
    comp = ShellComplete(cli, {}, cli.name, "_CLICK_COMPLETE")
    return comp.get_completions(args, incomplete)


def test_multiline_help_option():
    @click.command()
    @click.option(
        "--at",
        type=(str, str),
        multiple=True,
        help="\b\nAttachment with explicit mimetype,\n--at image.jpg image/jpeg"
    )
    def cli(at):
        pass

    # Check if the multi-line help text causes an error during completion
    with pytest.raises(Exception) as excinfo:
        _get_completions(cli, ["--at"], "")
    assert "unknown option" in str(excinfo.value)  # Check for specific error message"}}
